#[path = "solution.rs"]
mod solution;

use solution::{Appointment, AppointmentCatalog, CatalogCommand, CatalogError, CatalogReply};

fn appointment(id: &str, title: &str, date: &str, notes: &str) -> Appointment {
    Appointment { id: id.to_string(), title: title.to_string(), date: date.to_string(), notes: notes.to_string() }
}

fn found(catalog: &mut AppointmentCatalog, id: &str) -> Appointment {
    match catalog.execute(CatalogCommand::Fetch { id: id.to_string() }).unwrap() {
        CatalogReply::Found(value) => value,
        other => panic!("unexpected reply: {:?}", other),
    }
}

#[test]
fn new_and_default_are_empty() {
    for mut catalog in [AppointmentCatalog::new(), AppointmentCatalog::default()] {
        assert_eq!(catalog.execute(CatalogCommand::List), Ok(CatalogReply::Listed(vec![])));
    }
}

#[test]
fn create_fetch_and_replace_entire_appointment() {
    let mut catalog = AppointmentCatalog::new();
    let first = appointment("a", "Initial", "2026-01-01", "old");
    assert_eq!(catalog.execute(CatalogCommand::Create(first.clone())), Ok(CatalogReply::Stored(first.clone())));
    assert_eq!(found(&mut catalog, "a"), first);

    let replacement = appointment("a", "Updated", "", "");
    assert_eq!(catalog.execute(CatalogCommand::Replace(replacement.clone())), Ok(CatalogReply::Stored(replacement.clone())));
    assert_eq!(found(&mut catalog, "a"), replacement);
}

#[test]
fn list_is_sorted_by_id_and_does_not_mutate_catalog() {
    let mut catalog = AppointmentCatalog::new();
    let b = appointment("b", "B", "", "");
    let a = appointment("a", "A", "", "");
    catalog.execute(CatalogCommand::Create(b.clone())).unwrap();
    catalog.execute(CatalogCommand::Create(a.clone())).unwrap();

    assert_eq!(catalog.execute(CatalogCommand::List), Ok(CatalogReply::Listed(vec![a.clone(), b.clone()])));
    assert_eq!(catalog.execute(CatalogCommand::List), Ok(CatalogReply::Listed(vec![a, b])));
}

#[test]
fn empty_id_or_title_is_rejected_atomically() {
    let mut catalog = AppointmentCatalog::new();
    let original = appointment("x", "Original", "date", "notes");
    catalog.execute(CatalogCommand::Create(original.clone())).unwrap();

    assert_eq!(catalog.execute(CatalogCommand::Create(appointment("", "Title", "", ""))), Err(CatalogError::EmptyId));
    assert_eq!(catalog.execute(CatalogCommand::Create(appointment("y", "", "", ""))), Err(CatalogError::EmptyTitle));
    assert_eq!(catalog.execute(CatalogCommand::Replace(appointment("x", "", "changed", "changed"))), Err(CatalogError::EmptyTitle));
    assert_eq!(found(&mut catalog, "x"), original);
}

#[test]
fn duplicate_create_and_missing_operations_leave_state_unchanged() {
    let mut catalog = AppointmentCatalog::new();
    let original = appointment("x", "Original", "date", "notes");
    catalog.execute(CatalogCommand::Create(original.clone())).unwrap();

    assert_eq!(catalog.execute(CatalogCommand::Create(appointment("x", "Other", "", ""))), Err(CatalogError::AlreadyExists));
    assert_eq!(catalog.execute(CatalogCommand::Replace(appointment("missing", "Valid", "", ""))), Err(CatalogError::NotFound));
    assert_eq!(catalog.execute(CatalogCommand::Fetch { id: "missing".to_string() }), Err(CatalogError::NotFound));
    assert_eq!(found(&mut catalog, "x"), original);
}

#[test]
fn replies_are_owned_and_can_be_mutated_without_aliasing_storage() {
    let mut catalog = AppointmentCatalog::new();
    let original = appointment("x", "Original", "date", "notes");
    catalog.execute(CatalogCommand::Create(original.clone())).unwrap();

    let mut fetched = found(&mut catalog, "x");
    fetched.title.clear();
    fetched.notes.push_str("changed");

    let mut listed = match catalog.execute(CatalogCommand::List).unwrap() {
        CatalogReply::Listed(values) => values,
        other => panic!("unexpected reply: {:?}", other),
    };
    listed[0].id = "different".to_string();
    assert_eq!(found(&mut catalog, "x"), original);
}

